"""Candidate controller for SD3.5 OCR discovery."""

from __future__ import annotations

from flow_autotts.core.env import FlowTTSEnv
from flow_autotts.core.errors import BudgetExceededError, InvalidActionError
from flow_autotts.core.state import AnswerRecord, PreviewRecord


class OptimalController:
    """Completed-anchor best-of-N with beta-scaled late refinement."""

    def solve(self, env: FlowTTSEnv, beta: float) -> AnswerRecord:
        beta = min(max(float(beta), 0.0), 1.0)
        initial_budget = max(0, int(env.budget_left))

        root_id = env.spawn(1)[0]
        try:
            self._finish(env, root_id)
        except BudgetExceededError:
            return env.answer(rule="latest_active")

        if beta <= 0.0 or env.budget_left <= 0:
            return env.answer(rule="latest_active")

        target_nfe = self._target_nfe(initial_budget, beta, spent=initial_budget - env.budget_left)
        self._preview(env, root_id, target_nfe, initial_budget)

        step_count = max(1, len(env.time_grid) - 1)
        full_candidate_cost = step_count + 1
        full_candidates = max(1, min(5, 1 + int(4 * beta), target_nfe // full_candidate_cost))
        extra_roots = max(0, full_candidates - 1)
        if extra_roots > 0:
            for particle_id in env.spawn(extra_roots):
                if self._spent(env, initial_budget) + full_candidate_cost > target_nfe:
                    break
                try:
                    self._finish(env, particle_id)
                    self._preview(env, particle_id, target_nfe, initial_budget)
                except (BudgetExceededError, InvalidActionError):
                    break

        self._refine_from_best_previews(env, beta, target_nfe, initial_budget)
        return env.answer(rule="best_preview_score")

    def _target_nfe(self, initial_budget: int, beta: float, spent: int) -> int:
        if initial_budget <= spent:
            return spent
        extra = int((initial_budget - spent) * beta)
        if beta > 0.0:
            extra = max(1, extra)
        return min(initial_budget, spent + extra)

    def _finish(self, env: FlowTTSEnv, particle_id: int) -> None:
        state = env.get_state()
        current_time = state.particles[particle_id].time
        for target_time in env.time_grid:
            if target_time > current_time:
                env.forward(particle_id, target_time=target_time, solver="euler")
                current_time = target_time

    def _preview(
        self,
        env: FlowTTSEnv,
        particle_id: int,
        target_nfe: int,
        initial_budget: int,
    ) -> None:
        if self._spent(env, initial_budget) + 1 <= target_nfe and env.budget_left > 0:
            env.preview(particle_id, mode="clean_anchor", scorer="default")

    def _refine_from_best_previews(
        self,
        env: FlowTTSEnv,
        beta: float,
        target_nfe: int,
        initial_budget: int,
    ) -> None:
        target_time = self._backward_time(beta)
        noise_policy = "mixed_noise" if beta >= 0.6 else "fresh_noise"
        strength = 0.35 if noise_policy == "mixed_noise" else 1.0
        max_children = max(0, int(1 + 4 * beta))

        children_made = 0
        while children_made < max_children:
            previews = self._ranked_previews(env)
            if not previews:
                return
            anchor = previews[children_made % len(previews)]
            child_cost = self._child_finish_preview_cost(env, target_time)
            if self._spent(env, initial_budget) + child_cost > target_nfe:
                return
            try:
                child_id = env.backward(
                    anchor.id,
                    target_time=target_time,
                    noise_policy=noise_policy,
                    num_children=1,
                    strength=strength,
                )[0]
                self._finish(env, child_id)
                self._preview(env, child_id, target_nfe, initial_budget)
            except (BudgetExceededError, InvalidActionError):
                return
            children_made += 1

    def _ranked_previews(self, env: FlowTTSEnv) -> list[PreviewRecord]:
        state = env.get_state()
        previews = [
            preview
            for preview in state.previews.values()
            if preview.score is not None
            and preview.particle_id in state.particles
            and state.particles[preview.particle_id].status != "pruned"
        ]
        return sorted(
            previews,
            key=lambda preview: (
                float(preview.score),
                -float(preview.uncertainty or 0.0),
                float(preview.time),
            ),
            reverse=True,
        )

    def _child_finish_preview_cost(self, env: FlowTTSEnv, target_time: float) -> int:
        forward_steps = sum(1 for time in env.time_grid if time > target_time)
        return max(1, forward_steps) + 1

    def _backward_time(self, beta: float) -> float:
        if beta >= 0.8:
            return 0.65
        if beta >= 0.5:
            return 0.75
        return 0.85

    def _spent(self, env: FlowTTSEnv, initial_budget: int) -> int:
        return max(0, int(initial_budget - env.budget_left))

"""Baseline controllers from the implementation spec."""

from __future__ import annotations

from flow_autotts.core.env import FlowTTSEnv
from flow_autotts.core.errors import BudgetExceededError
from flow_autotts.core.state import AnswerRecord


def map_beta(beta: float) -> dict[str, float | int]:
    beta = min(max(float(beta), 0.0), 1.0)
    return {
        "max_particles": int(2 + 14 * beta),
        "max_preview_calls": int(2 + 12 * beta),
        "max_backward_children": int(1 + 4 * beta),
        "min_keep": int(1 + 3 * beta),
        "early_time": 0.25,
        "mid_time": 0.55,
        "late_time": 0.80,
    }


class DeterministicController:
    def solve(self, env: FlowTTSEnv, beta: float) -> AnswerRecord:
        particle_id = env.spawn(1)[0]
        for target_time in env.time_grid[1:]:
            env.forward(particle_id, target_time=target_time, solver="euler")
        return env.answer(rule="latest_active")


class BestOfNController:
    def solve(self, env: FlowTTSEnv, beta: float) -> AnswerRecord:
        requested = int(map_beta(beta)["max_particles"])
        per_particle_cost = max(1, len(env.time_grid) - 1) + 1
        affordable = max(1, env.budget // per_particle_cost)
        n = min(requested, affordable)
        ids = env.spawn(n)

        for particle_id in ids:
            for target_time in env.time_grid[1:]:
                env.forward(particle_id, target_time=target_time, solver="euler")
            env.preview(particle_id, scorer="default")

        return env.answer(rule="best_preview_score")


class SDEForwardController:
    """Best-of-N controller using Flow-GRPO-style SDE forward steps."""

    def solve(self, env: FlowTTSEnv, beta: float) -> AnswerRecord:
        beta = min(max(float(beta), 0.0), 1.0)
        requested = int(2 + 14 * beta)
        per_particle_cost = max(1, len(env.time_grid) - 1) + 1
        affordable = max(1, env.budget // per_particle_cost)
        n = min(requested, affordable)
        noise_scale = self._noise_scale(beta)
        ids = env.spawn(n)

        for particle_id in ids:
            for target_time in env.time_grid[1:]:
                env.forward(
                    particle_id,
                    target_time=target_time,
                    solver="sde",
                    cfg={"noise_scale": noise_scale, "sigma_max": 1.25, "min_time": 0.02},
                )
            env.preview(particle_id, scorer="default")

        return env.answer(rule="best_preview_score")

    @staticmethod
    def _noise_scale(beta: float) -> float:
        if beta <= 0.0:
            return 0.03
        if beta < 0.5:
            return 0.0
        if beta < 0.75:
            return 0.01
        return 0.008


class SelfRefineController:
    def solve(self, env: FlowTTSEnv, beta: float) -> AnswerRecord:
        beta = min(max(float(beta), 0.0), 1.0)
        refinement_rounds = int(1 + 3 * beta)
        particle_id = env.spawn(1)[0]

        for target_time in env.time_grid[1:]:
            state = env.get_state().particles[particle_id]
            current_time = state.time
            if current_time < 0.35:
                for _ in range(refinement_rounds):
                    preview = env.preview(
                        particle_id,
                        mode="clean_anchor",
                        scorer=None,
                    )
                    particle_id = env.backward(
                        preview.id,
                        target_time=current_time,
                        noise_policy="fresh_noise",
                        num_children=1,
                    )[0]
            env.forward(particle_id, target_time=target_time, solver="euler")

        return env.answer(rule="latest_active")


class PrismStyleFlowController:
    def solve(self, env: FlowTTSEnv, beta: float) -> AnswerRecord:
        params = map_beta(beta)
        warm_target = float(params["mid_time"])
        finish_grid = [t for t in env.time_grid if t > warm_target]
        if not finish_grid or finish_grid[-1] < 1.0:
            finish_grid.append(1.0)

        per_root_cost = 2
        requested_roots = int(params["max_particles"])
        root_budget = max(1, env.budget // max(1, per_root_cost + len(finish_grid)))
        root_count = min(requested_roots, root_budget)
        ids = env.spawn(root_count)

        previewed_ids: list[int] = []
        for particle_id in ids:
            if env.budget_left < per_root_cost:
                break
            env.forward(particle_id, target_time=warm_target, solver="euler")
            env.preview(particle_id, mode="clean_anchor", scorer="default")
            previewed_ids.append(particle_id)

        if not previewed_ids:
            return env.answer(rule="latest_active")

        state = env.get_state()
        ranked = sorted(
            previewed_ids,
            key=lambda pid: (
                state.previews[state.particles[pid].last_preview_id].score
                if state.particles[pid].last_preview_id is not None
                and state.previews[state.particles[pid].last_preview_id].score is not None
                else float("-inf")
            ),
            reverse=True,
        )
        keep = min(len(ranked), int(params["min_keep"]))
        survivors = ranked[:keep]
        env.prune([pid for pid in ranked if pid not in survivors])

        child_ids: list[int] = []
        children_per_anchor = int(params["max_backward_children"])
        for particle_id in survivors:
            preview_id = env.get_state().particles[particle_id].last_preview_id
            if preview_id is None:
                continue
            child_ids.extend(
                env.backward(
                    preview_id,
                    target_time=warm_target,
                    noise_policy="fresh_noise",
                    num_children=children_per_anchor,
                )
            )

        if not child_ids:
            return env.answer(rule="best_preview_score")

        finished: list[int] = []
        for particle_id in child_ids:
            needed = len([t for t in finish_grid if t > warm_target])
            if env.budget_left < needed + 1:
                break
            try:
                for target_time in finish_grid:
                    if env.get_state().particles[particle_id].status == "active":
                        env.forward(particle_id, target_time=target_time, solver="euler")
                env.preview(particle_id, scorer="default")
                finished.append(particle_id)
            except BudgetExceededError:
                break

        if not finished:
            return env.answer(rule="best_preview_score")
        return env.answer(rule="best_preview_score")

"""Environment exceptions."""


class FlowTTSError(RuntimeError):
    """Base class for environment failures."""


class BudgetExceededError(FlowTTSError):
    """Raised when an action would exceed the episode budget."""


class InvalidActionError(FlowTTSError):
    """Raised when a controller requests an invalid action."""

"""Candidate controller for SD3.5 OCR discovery."""

from __future__ import annotations

from flow_autotts.core.env import FlowTTSEnv
from flow_autotts.core.errors import BudgetExceededError, InvalidActionError
from flow_autotts.core.state import AnswerRecord, PreviewRecord


class OptimalController:
    """Preview-driven controller with beta-scaled confirmation and refinement."""

    def solve(self, env: FlowTTSEnv, beta: float) -> AnswerRecord:
        beta = min(max(float(beta), 0.0), 1.0)
        schedule = self._schedule(env, beta)
        initial_budget = max(0, int(env.budget_left))
        target_nfe = min(initial_budget, int(schedule["target_nfe"]))

        try:
            root_ids = env.spawn(int(schedule["root_count"]))
        except InvalidActionError:
            return env.answer(rule="latest_active")

        if not root_ids:
            return env.answer(rule="latest_active")

        root_ids = root_ids[: self._affordable_roots(env, target_nfe, initial_budget, schedule)]
        if not root_ids:
            return env.answer(rule="latest_active")

        self._scout_roots(env, root_ids, schedule, target_nfe, initial_budget)
        self._prune_after_scout(env, schedule)
        self._finish_survivors(env, schedule, target_nfe, initial_budget)
        self._confirm_top_anchors(env, schedule, target_nfe, initial_budget)
        self._refine_best_anchors(env, schedule, target_nfe, initial_budget)
        self._spend_tail_budget(env, schedule, target_nfe, initial_budget)
        return self._safe_answer(env)

    def _schedule(self, env: FlowTTSEnv, beta: float) -> dict[str, float | int | bool | str]:
        step_count = max(1, len(env.time_grid) - 1)
        target_nfe = int(round(10.0 + 54.0 * (beta**1.1)))
        target_nfe = min(int(env.budget), max(10, target_nfe))

        if beta <= 0.0:
            return {
                "target_nfe": min(int(env.budget), 10),
                "root_count": 2,
                "scout_time": 0.6,
                "survivor_count": 1,
                "confirm_count": 1,
                "confirm_steps": 0,
                "backward_children": 0,
                "backward_time": 0.9,
                "noise_policy": "fresh_noise",
                "noise_strength": 1.0,
                "prune_margin": 0.35,
                "uncertainty_gate": 0.45,
                "late_preview_rounds": 0,
                "use_sde_scout": False,
                "step_count": step_count,
            }

        return {
            "target_nfe": target_nfe,
            "root_count": 2 + int(3 * beta),
            "scout_time": 0.4 + 0.2 * beta,
            "survivor_count": 1 + int(2 * beta),
            "confirm_count": 1 + int(2 * beta),
            "confirm_steps": int(1 + 2 * beta),
            "backward_children": int(1 + 3 * beta),
            "backward_time": 0.86 - 0.18 * beta,
            "noise_policy": "mixed_noise" if beta >= 0.65 else "fresh_noise",
            "noise_strength": 0.45 if beta >= 0.65 else 1.0,
            "prune_margin": 0.18 - 0.08 * beta,
            "uncertainty_gate": 0.52 - 0.18 * beta,
            "late_preview_rounds": int(1 + 3 * beta),
            "use_sde_scout": beta >= 0.75,
            "step_count": step_count,
        }

    def _affordable_roots(
        self,
        env: FlowTTSEnv,
        target_nfe: int,
        initial_budget: int,
        schedule: dict[str, float | int | bool | str],
    ) -> int:
        scout_step = self._time_to_step(env, float(schedule["scout_time"]))
        scout_cost = max(1, scout_step) + 1
        remaining = max(1, target_nfe - self._spent(env, initial_budget))
        return max(1, min(int(schedule["root_count"]), remaining // max(1, scout_cost)))

    def _scout_roots(
        self,
        env: FlowTTSEnv,
        root_ids: list[int],
        schedule: dict[str, float | int | bool | str],
        target_nfe: int,
        initial_budget: int,
    ) -> None:
        scout_time = float(schedule["scout_time"])
        solver = "sde" if bool(schedule["use_sde_scout"]) else "euler"
        cfg = {"noise_scale": 0.01, "sde_type": "sde"} if solver == "sde" else None
        for particle_id in root_ids:
            if not self._can_afford(env, target_nfe, initial_budget, self._move_cost(env, particle_id, scout_time) + 1):
                return
            try:
                self._forward_to(env, particle_id, scout_time, solver=solver, cfg=cfg)
                self._preview(env, particle_id, target_nfe, initial_budget)
            except (BudgetExceededError, InvalidActionError):
                return

    def _prune_after_scout(
        self,
        env: FlowTTSEnv,
        schedule: dict[str, float | int | bool | str],
    ) -> None:
        previews = self._ranked_previews(env)
        if len(previews) <= int(schedule["survivor_count"]):
            return

        best = float(previews[0].score or 0.0)
        keep_ids: list[int] = []
        for index, preview in enumerate(previews):
            gap = best - float(preview.score or 0.0)
            if index < int(schedule["survivor_count"]) or gap <= float(schedule["prune_margin"]):
                keep_ids.append(preview.particle_id)

        prune_ids = [
            preview.particle_id
            for preview in previews
            if preview.particle_id not in keep_ids and self._is_active(env, preview.particle_id)
        ]
        if prune_ids:
            try:
                env.prune(prune_ids)
            except InvalidActionError:
                return

    def _finish_survivors(
        self,
        env: FlowTTSEnv,
        schedule: dict[str, float | int | bool | str],
        target_nfe: int,
        initial_budget: int,
    ) -> None:
        previews = self._ranked_previews(env)
        if not previews:
            return
        survivors = previews[: int(schedule["survivor_count"])]
        for preview in survivors:
            pid = preview.particle_id
            if not self._is_active(env, pid):
                continue
            need_preview = self._needs_confirmation(preview, schedule)
            cost = self._move_cost(env, pid, 1.0) + (1 if need_preview else 0)
            if not self._can_afford(env, target_nfe, initial_budget, cost):
                continue
            try:
                self._forward_to(env, pid, 1.0, solver="euler", cfg=None)
                if need_preview:
                    self._preview(env, pid, target_nfe, initial_budget)
            except (BudgetExceededError, InvalidActionError):
                continue

    def _confirm_top_anchors(
        self,
        env: FlowTTSEnv,
        schedule: dict[str, float | int | bool | str],
        target_nfe: int,
        initial_budget: int,
    ) -> None:
        confirm_count = int(schedule["confirm_count"])
        confirm_steps = int(schedule["confirm_steps"])
        if confirm_count <= 0 or confirm_steps <= 0:
            return

        previews = self._ranked_previews(env)[:confirm_count]
        for preview in previews:
            pid = preview.particle_id
            if not self._is_active(env, pid):
                continue
            next_time = self._advance_time(env, pid, confirm_steps)
            if next_time is None:
                continue
            cost = self._move_cost(env, pid, next_time) + 1
            if not self._can_afford(env, target_nfe, initial_budget, cost):
                continue
            try:
                self._forward_to(env, pid, next_time, solver="euler", cfg=None)
                self._preview(env, pid, target_nfe, initial_budget)
            except (BudgetExceededError, InvalidActionError):
                continue

    def _refine_best_anchors(
        self,
        env: FlowTTSEnv,
        schedule: dict[str, float | int | bool | str],
        target_nfe: int,
        initial_budget: int,
    ) -> None:
        children_budget = int(schedule["backward_children"])
        if children_budget <= 0:
            return

        launched = 0
        for anchor in self._refinement_candidates(env):
            if launched >= children_budget:
                break
            per_child_cost = self._child_cost(env, float(schedule["backward_time"]))
            if not self._can_afford(env, target_nfe, initial_budget, per_child_cost):
                return
            child_count = 1
            if launched + 1 < children_budget and self._gap_to_next(env, anchor.id) <= 0.05:
                child_count = min(2, children_budget - launched)
            try:
                child_ids = env.backward(
                    anchor.id,
                    target_time=float(schedule["backward_time"]),
                    noise_policy=str(schedule["noise_policy"]),
                    num_children=child_count,
                    strength=float(schedule["noise_strength"]),
                )
            except (BudgetExceededError, InvalidActionError):
                continue
            for child_id in child_ids:
                if launched >= children_budget:
                    break
                if not self._can_afford(env, target_nfe, initial_budget, per_child_cost):
                    return
                try:
                    self._forward_to(env, child_id, 1.0, solver="euler", cfg=None)
                    self._preview(env, child_id, target_nfe, initial_budget)
                except (BudgetExceededError, InvalidActionError):
                    return
                launched += 1

    def _spend_tail_budget(
        self,
        env: FlowTTSEnv,
        schedule: dict[str, float | int | bool | str],
        target_nfe: int,
        initial_budget: int,
    ) -> None:
        rounds = int(schedule["late_preview_rounds"])
        while rounds > 0 and self._spent(env, initial_budget) < target_nfe:
            best = self._best_live_preview(env)
            if best is None:
                return
            pid = best.particle_id
            if self._is_active(env, pid):
                next_time = self._advance_time(env, pid, 1)
                if next_time is not None and self._can_afford(env, target_nfe, initial_budget, self._move_cost(env, pid, next_time) + 1):
                    try:
                        self._forward_to(env, pid, next_time, solver="euler", cfg=None)
                        self._preview(env, pid, target_nfe, initial_budget)
                        rounds -= 1
                        continue
                    except (BudgetExceededError, InvalidActionError):
                        return

                    return
        for anchor in self._refinement_candidates(env):
            child_cost = self._child_cost(env, float(schedule["backward_time"]))
            if not self._can_afford(env, target_nfe, initial_budget, child_cost):
                break
            try:
                child_ids = env.backward(
                    anchor.id,
                    target_time=float(schedule["backward_time"]),
                    noise_policy=str(schedule["noise_policy"]),
                    num_children=1,
                    strength=float(schedule["noise_strength"]),
                )
                for child_id in child_ids:
                    self._forward_to(env, child_id, 1.0, solver="euler", cfg=None)
                    self._preview(env, child_id, target_nfe, initial_budget)
                    rounds -= 1
                    break
                if rounds <= 0:
                    return
            except (BudgetExceededError, InvalidActionError):
                continue
